package dev.koikaster.mite;
import java.util.function.DoubleSupplier;import net.minecraft.core.BlockPos;import net.minecraft.server.level.ServerPlayer;import net.minecraft.util.Mth;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.CollisionContext;import net.minecraftforge.event.TickEvent;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.fml.common.Mod;
/** jv.isUnderworldBottomBedrockVisible. setForVision(false) means retain leaf impedance. */
@Mod.EventBusSubscriber(modid=MiteReforged.ID)
public final class SourceBottomSight579 {
 private static boolean glass(BlockState state){var b=state.getBlock();return b instanceof AbstractGlassBlock||b instanceof StainedGlassPaneBlock||state.is(Blocks.GLASS_PANE)||state.is(Blocks.GLOWSTONE)||state.is(Blocks.BEACON)||state.is(Blocks.SEA_LANTERN)||b instanceof IceBlock||state.is(Blocks.PACKED_ICE)||state.is(Blocks.BLUE_ICE);}
 private static boolean portal(BlockState state){var b=state.getBlock();return b instanceof DoorBlock||b instanceof TrapDoorBlock||b instanceof FenceGateBlock||b instanceof NetherPortalBlock||b instanceof EndPortalBlock||state.is(Blocks.END_GATEWAY);}
 private static boolean sparse(BlockState state){var b=state.getBlock();return b instanceof TallGrassBlock||b instanceof FlowerBlock||b instanceof DoublePlantBlock||b instanceof CropBlock||b instanceof WebBlock||b instanceof SugarCaneBlock||b instanceof VineBlock||b instanceof LeavesBlock;}
 public static Vec3 direction(float yaw,float pitch){float a=Mth.cos(-yaw*((float)Math.PI/180)-(float)Math.PI),b=Mth.sin(-yaw*((float)Math.PI/180)-(float)Math.PI),c=-Mth.cos(-pitch*((float)Math.PI/180)),d=Mth.sin(-pitch*((float)Math.PI/180));return new Vec3(b*c,d,a*c);}
 public static BlockHitResult first(ServerPlayer player,Vec3 origin,Vec3 limit){int[] impedance={0};var level=player.level();return SourceVisionDda579.trace(origin,limit,(x,y,z,from,to)->{var pos=new BlockPos(x,y,z);var state=level.getBlockState(pos);var b=state.getBlock();if(state.isAir()||b instanceof LiquidBlock||glass(state)||portal(state)||b instanceof FenceBlock||b instanceof IronBarsBlock)return null;if(sparse(state)&&(impedance[0]+=50)<100)return null;var context=CollisionContext.of(player);var shape=b instanceof HopperBlock||b instanceof AbstractCauldronBlock?state.getCollisionShape(level,pos,context):state.getShape(level,pos,context);return shape.clip(from,to,pos);});}
 public static boolean visible(ServerPlayer player,DoubleSupplier random){if(player.level().dimension()!=WorldEvents.UNDERWORLD||Mth.floor(player.getY()+1e-4f)>20)return false;float yaw=(float)(player.getYRot()+(random.getAsDouble()*181d-90d)),pitch=(float)(player.getXRot()+(random.getAsDouble()*181d-90d));var origin=player.getEyePosition();var hit=first(player,origin,origin.add(direction(yaw,pitch).scale(16d)));return hit!=null&&hit.getBlockPos().getY()<5&&player.level().getBlockState(hit.getBlockPos()).getBlock() instanceof SourceMantleBlock;}
 @SubscribeEvent public static void tick(TickEvent.PlayerTickEvent event){if(event.phase==TickEvent.Phase.END&&event.player instanceof ServerPlayer player&&visible(player,Math::random))SourceAchievementService570.grant(player,"portalToNether");}
 private SourceBottomSight579(){}
}
